css:
.header{
    border-bottom:2px solid #1E3A8A;
    padding-bottom:12px;
    margin-bottom:20px;
}

.header-table{
    width:100%;
    border-collapse:collapse;
}

.logo-cell{
    width:70px;
    vertical-align:middle;
}

.company-logo{
    width:60px;
    height:60px;
    object-fit:contain;
}

.company-cell{
    vertical-align:middle;
    padding-left:12px;
}

.company-name{
    font-size:16px;
    font-weight:bold;
    color:#1E3A8A;
    margin-bottom:6px;
     margin-top:8px;
    
}

.company-address{
    font-size:10px;
    color:#555;
    line-height:1.5;
}

.title-cell{
    width:180px;
    text-align:right;
    vertical-align:middle;
}

.payslip-title{
    font-size:24px;
    font-weight:bold;
    color:#1E3A8A;
    letter-spacing:1px;
}

.payslip-month{
    font-size:24px;
    color:#666;
    margin-top:1px;
}
.badge-green{
    display:inline-block;
    min-width:40px;
    padding:4px 10px;
    text-align:center;
    font-size:11px;
    font-weight:bold;
    color:#155724;
    background:#d4edda;
    border:1px solid #c3e6cb;
    border-radius:4px;
}

.badge-blue{
    display:inline-block;
    min-width:40px;
    padding:4px 10px;
    text-align:center;
    font-size:11px;
    font-weight:bold;
    color:#155724;
    background:#f2f298;
    border:1px solid #c3e6cb;
    border-radius:4px;
}

.badge-red{
    display:inline-block;
    min-width:40px;
    padding:4px 10px;
    text-align:center;
    font-size:11px;
    font-weight:bold;
    color:#721c24;
    background:#f8d7da;
    border:1px solid #f5c6cb;
    border-radius:4px;
}

.detail-box{
    border:1px solid #d8d8d8;
    border-radius:8px;
    padding:10px;
    margin-bottom:15px;
    background:#fff;
}

.detail-table{
    width:100%;
    border-collapse:collapse;
}

.detail-table td{
    width:33.33%;
    text-align:center;
    padding:10px;
    border-right:1px solid #e5e5e5;
    vertical-align:middle;
}

.detail-table td:last-child{
    border-right:none;
}

.info-title{
    font-size:11px;
    font-weight:bold;
    color:#1E3A8A;
    text-transform:uppercase;
    margin-bottom:6px;
}

.info-value{
    font-size:13px;
    font-weight:600;
    color:#333;
    word-break:break-word;
}
.table-box{
    border:1px solid #d8d8d8;
    border-radius:8px;
    overflow:hidden;
    margin-bottom:18px;
    background:#fff;
}

.salary-table{
    width:100%;
    border-collapse:collapse;
}

.salary-table thead th{
    background:#1E3A8A;
    color:#fff;
    font-size:12px;
    font-weight:bold;
    text-transform:uppercase;
    padding:10px;
    border-right:1px solid #ffffff30;
}

.salary-table thead th:last-child{
    border-right:none;
}

.salary-table td{
    padding:8px 10px;
    border-top:1px solid #e5e5e5;
    border-right:1px solid #f0f0f0;
    font-size:12px;
}

.salary-table td:last-child{
    border-right:none;
}

.salary-table tbody tr:nth-child(even){
    background:#fafafa;
}

.total-row{
    background:#eef4ff;
    font-weight:bold;
}

.total-row td{
    border-top:2px solid #1E3A8A;
    color:#1E3A8A;
}

.text-right{
    text-align:right;
}
